// v23.xx (gfx19), HIS ORDER (2026-10-12) on the graphics program, item 7: THE WHITE HIT FLASH. On the frame a pillager or a
// machine is hit (the first frame of its hit pause, gfx18), its silhouette flashes white over it, once, at 85 percent times
// EFFECT INTENSITY (none at OFF). The body is painted a second time into one small shared scratch canvas (HITSIL) with the
// same camera, its ground shadow left out (GFX_NOSHAD), made solid white and stamped back over the frame. Drawn only, never
// in the sim, nothing written onto the body. The red hurt wash and the hit jolt still play after it.
var HITSIL=null, GFX_NOSHAD=0;
function gfxBodyPaint(e){
  var k=e&&e.kind;
  if(k==='choir') drawChoirS(e); else if(k==='warden') drawWardenAt(e); else if(k==='sentry') drawSentryS(e);
  else if(k==='crawler') drawCrawlerS(e); else if(k==='snitch') drawSnitchS(e); else if(k==='listener') drawListenerS(e);
  else if(k==='howler') drawHowlerS(e); else if(k==='bulwark') drawBulwarkS(e); else if(k==='peddler') drawPeddlerS(e);
  else if(k==='raider') drawOp(e.x,e.y,e.face,(e.roll>0)?(1-e.roll/.38)*12.6:(e.step||0)*4,e.coat||'#808080',0,0,
    (e.downed||e.state==='down')?'down':((e.roll>0)?'roll':(raiderCrouched(e)?'crouch':'')),0,
    {own:e,team:'foe',moving:!!e.moving,sprint:e.state==='extract',ads:e.state==='chase',hurt:0,bulk:e.bulk||0,hair:e.hair,cut:e.cut,hat:e.hat,build:e.build});
  else return 0;
  return 1;
}
function gfxHitFlash(e){
  var s, m, sc, S, dx, dy, x2, w0, k, ok=0;
  if(!HITP||!e||typeof G==='undefined'||!G||G.sim||typeof document==='undefined') return 0;
  s=HITP.get(e); if(!(s&&s.on&&s.tf===(G.t||0))) return 0;
  k=(CFG.fxInt===undefined||CFG.fxInt===null)?1:+CFG.fxInt; if(!(k>0)) return 0;
  m=wc.getTransform(); sc=Math.hypot(m.a,m.b); if(!(sc>0)) return 0;
  S=Math.min(1024,Math.ceil(170*sc));
  if(!HITSIL) HITSIL=document.createElement('canvas');
  if(HITSIL.width!==S||HITSIL.height!==S){ HITSIL.width=S; HITSIL.height=S; }
  x2=HITSIL.getContext('2d'); if(!x2) return 0;
  dx=m.a*e.x+m.c*(e.y-30)+m.e; dy=m.b*e.x+m.d*(e.y-30)+m.f;
  x2.setTransform(1,0,0,1,0,0); x2.globalCompositeOperation='source-over'; x2.globalAlpha=1; x2.clearRect(0,0,S,S);
  x2.setTransform(m.a,m.b,m.c,m.d,m.e-dx+S/2,m.f-dy+S/2);
  w0=wc; wc=x2; GFX_NOSHAD=1;
  try{ ok=gfxBodyPaint(e); }catch(_bp){ ok=0; } finally{ wc=w0; GFX_NOSHAD=0; }
  if(!ok) return 0;
  x2.setTransform(1,0,0,1,0,0); x2.globalAlpha=1; x2.globalCompositeOperation='source-in'; x2.fillStyle='#ffffff'; x2.fillRect(0,0,S,S); x2.globalCompositeOperation='source-over';
  wc.save(); wc.setTransform(1,0,0,1,0,0); wc.globalCompositeOperation='source-over'; wc.globalAlpha=0.85*Math.min(1,k); wc.drawImage(HITSIL,dx-S/2,dy-S/2); wc.restore();
  return 1;
}

